findings.codeql_raw_query:
/**
 * @name Taint-style flow from untrusted input to HTML escaping APIs
 * @description Ensure MarkupSafe does not accidentally double-escape or bypass escaping when wrapping strings.
 * @kind path-problem
 * @problem.severity warning
 * @id py/markupsafe-taint-to-escape
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module EscapeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("markupsafe").getMember(["escape", "Markup"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module EscapeFlow = TaintTracking::Global<EscapeConfig>;
import EscapeFlow::PathGraph

from EscapeFlow::PathNode source, EscapeFlow::PathNode sink
where EscapeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into MarkupSafe escaping APIs at $@.", source.getNode(), "user input"
